package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Window;import org.brightstats.stats.*;import org.brightstats.data.*;
final class HierarchyPipelineDialog {
 enum Estimator{COMPOSITE,PLSC_MOMENTS}
 record Settings(Estimator estimator,HierarchyPipeline.Model model,List<String> sourceNames){Settings{Objects.requireNonNull(estimator);Objects.requireNonNull(model);sourceNames=List.copyOf(sourceNames);HierarchyPipeline.validate(sourceNames.size(),model);}void validateSource(List<String> names,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options){if(names.size()<sourceNames.size()||!names.subList(0,sourceNames.size()).equals(sourceNames))throw new IllegalArgumentException("Hierarchy source bindings changed; configure it again.");Gson gson=new GsonBuilder().serializeNulls().create();if(!gson.toJsonTree(model.blocks()).equals(gson.toJsonTree(blocks))||!model.edges().equals(edges)||!model.options().equals(options))throw new IllegalArgumentException("The source model changed; configure the hierarchy transitions again rather than using stale indices.");}}
 private final Dialog<Settings> dialog=new Dialog<>();private final ComboBox<Estimator> estimator=new ComboBox<>();private final TextArea stages=new TextArea();private final Label error=new Label();private Settings result;private final List<String> names;private final List<PlsSem.Block> blocks;private final List<PlsSem.Edge> edges;private final PlsSem.Options options;private final Gson json=new GsonBuilder().serializeNulls().setPrettyPrinting().create();
 private HierarchyPipelineDialog(Window owner,List<String> names,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Settings previous){this.names=List.copyOf(names);this.blocks=List.copyOf(blocks);this.edges=List.copyOf(edges);this.options=options;dialog.initOwner(owner);dialog.setTitle("Multi-level higher-order pipeline");dialog.setResizable(true);estimator.getItems().setAll(Estimator.values());estimator.setValue(previous==null?Estimator.COMPOSITE:previous.estimator());stages.setText(previous==null?"[]":json.toJson(previous.model().stages()));stages.setPrefRowCount(20);Button add=new Button("Add hierarchy transition...");add.setOnAction(event->{try{List<HigherOrderPls.Specification> current=parseStages();int width=names.size();List<PlsSem.Block> currentBlocks=this.blocks;List<PlsSem.Edge> currentEdges=this.edges;PlsSem.Options currentOptions=this.options;for(var specification:current){var next=HigherOrderPls.stageTwoBlocks(width,currentBlocks,currentEdges,specification);width+=currentBlocks.size();currentBlocks=next;currentEdges=specification.edges();currentOptions=specification.options();}var choice=HigherOrderDialog.show(dialog.getDialogPane().getScene().getWindow(),width,currentBlocks,currentEdges,currentOptions,null,false);if(choice.isPresent()){current.add(choice.get().specification());stages.setText(json.toJson(current));}}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});Label guidance=UiAppearance.label("Every transition refers to the previous model's construct order: retained constructs first, then its new higher-order definitions. Add one to seven transitions. Composite mode carries newly fitted case scores; PLSc moments correct source and higher-order factor correlations without exposing artificial individual scores. Reflective factors require Mode A and at least three indicators/dimensions in the PLSc moment contract.");guidance.setWrapText(true);Label ordering=UiAppearance.label(String.join("; ",java.util.stream.IntStream.range(0,blocks.size()).mapToObj(i->i+" = "+blocks.get(i).name()).toList()));ordering.setWrapText(true);ListView<String> steps=new ListView<>();steps.setPrefHeight(130);Runnable refresh=()->{try{steps.getItems().setAll(java.util.stream.IntStream.range(0,parseStages().size()).mapToObj(i->"Transition "+(i+1)+": "+parseStages().get(i).higherOrder().stream().map(HigherOrderPls.Dimension::name).collect(java.util.stream.Collectors.joining(", "))).toList());}catch(RuntimeException invalid){error.setText(invalid.getMessage());}};stages.textProperty().addListener((o,a,b)->refresh.run());refresh.run();Button remove=new Button("Remove final transition");remove.setOnAction(event->{try{var value=parseStages();if(!value.isEmpty())value.removeLast();stages.setText(json.toJson(value));}catch(RuntimeException invalid){error.setText(invalid.getMessage());}});TitledPane advanced=new TitledPane("Inspect / edit transition JSON",stages);advanced.setExpanded(false);VBox content=new VBox(10,guidance,ordering,estimator,steps,new HBox(8,add,remove),advanced,error);content.setPrefWidth(780);ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(650);dialog.getDialogPane().setContent(scroll);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{result=new Settings(estimator.getValue(),new HierarchyPipeline.Model(this.blocks,this.edges,this.options,parseStages()),this.names);error.setText("");}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});error.setWrapText(true);dialog.setResultConverter(button->button==ButtonType.OK?result:null);}
 private List<HigherOrderPls.Specification> parseStages(){List<HigherOrderPls.Specification> parsed=new ArrayList<>();for(var stage:BoundedJson.parse(stages.getText()).getAsJsonArray())parsed.add(HigherOrderInput.specification(stage));return parsed;}
 static Optional<Settings> show(Window owner,List<String> names,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options options,Settings previous){return new HierarchyPipelineDialog(owner,names,blocks,edges,options,previous).dialog.showAndWait();}
 static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var o=value.getAsJsonObject();List<String> names=new ArrayList<>();for(var name:o.getAsJsonArray("sourceNames"))names.add(name.getAsString());return new Settings(Estimator.valueOf(o.get("estimator").getAsString()),HierarchyInput.model(o.get("model")),names);}
 static Settings smoke(Window owner,List<String> names,HierarchyPipeline.Model model,java.nio.file.Path image)throws Exception{var previous=new Settings(Estimator.PLSC_MOMENTS,model,names);var controls=new HierarchyPipelineDialog(owner,names,model.blocks(),model.edges(),model.options(),previous);controls.dialog.show();var run=(Button)controls.dialog.getDialogPane().lookupButton(ButtonType.OK);String original=controls.stages.getText();controls.stages.setText("[]");run.fire();if(!controls.dialog.isShowing()||controls.result!=null)throw new AssertionError("Empty hierarchy accepted");controls.stages.setText(original);controls.error.setText("");controls.dialog.getDialogPane().applyCss();controls.dialog.getDialogPane().layout();java.nio.file.Files.deleteIfExists(image);GraphicExport.png(image,controls.dialog.getDialogPane(),1);run.fire();var result=controls.dialog.getResult();if(result==null||result.estimator()!=Estimator.PLSC_MOMENTS||result.model().stages().size()!=2)throw new AssertionError("Hierarchy dialog changed settings");return result;}
}
